/* cppi::c6a810eca92d0d82aa524412e04e0bdefd8bd638f122bf7df70594de7c9c6b7c */
select business_date as date_, security_id, 'SP500_30' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-12' and business_date <= date '2025-06-12' and weight_ndo>0 and id_cppib_index = 'SP500_30_GR_USD_0_0' and security_id is not null

/* cppi::5d7febb2827086642547de530ac53e872677932ba859aead71ae242d62ea20e1 */
select 
asec.cppib_sec_id AS "cppib_security_id",
asec.cppib_currency_of_exposure_code AS "Exposure Currency"

from asset.asset_security_enterprise_classifications asec where business_date =  CAST('2025-06-12' AS DATE)

/* cppi::f0cc67136091b55d58276c632f885d362181840675228e701e35c343a5d48498 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-04-08' and end_date = '2025-04-08')
and start_date = '2025-04-08' and end_date = '2025-04-08'

/* cppi::1cd2865f9e15210fc60f9257c001ce72275ddbcf1acbc240fa3f701f277b6963 */
SELECT * FROM "df_alternative_assets_qa"."dealcloud_pe_opportunity_extract"
where date = '20250606'

/* cppi::0703e8434d42ff28d9317a5f60423704a8fb6585db6d3bec144c7c84f916348e */
